const corsOrigins = process.env.CORS_ORIGIN ? process.env.CORS_ORIGIN.split(',').map(x => x.trim()).filter(Boolean) : ['http://localhost:5173'];
app.use(cors({ origin: (origin, cb) => !origin || corsOrigins.includes(origin) ? cb(null, true) : cb(new Error('CORS origin denied')), credentials: true }));
app.use(express.json({ limit: '1mb', strict: true }));
