const sign = (u) => jwt.sign({ sub: u.id, role: u.role_name, login_id: u.login_id, token_version: Number(u.auth_token_version || 0) }, JWT_SECRET, { expiresIn: '8h' });

async function auth(req, res, next) {
  try {
    const header = String(req.headers.authorization || '');
    if (!/^Bearer\s+[^\s]+$/i.test(header)) throw new Error('missing token');
    const token = header.replace(/^Bearer\s+/i, '');
    const claims = jwt.verify(token, JWT_SECRET);
    const q = await pool.query(`SELECT u.id,u.login_id,u.full_name,u.is_active,u.must_change_password,u.auth_token_version,r.name role_name FROM users u JOIN roles r ON r.id=u.role_id WHERE u.id=$1 LIMIT 1`, [claims.sub]);
    if (!q.rowCount || !q.rows[0].is_active) throw new Error('inactive user');
    if (Number(claims.token_version || 0) !== Number(q.rows[0].auth_token_version || 0)) throw new Error('stale session');
    req.user = { ...claims, sub: q.rows[0].id, login_id: q.rows[0].login_id, role: q.rows[0].role_name, full_name: q.rows[0].full_name, must_change_password: q.rows[0].must_change_password };
    if (req.user.must_change_password && !req.path.endsWith('/change-password')) {
      return res.status(403).json({ message: 'পাসওয়ার্ড পরিবর্তন না করা পর্যন্ত এই কাজ করা যাবে না', code: 'PASSWORD_CHANGE_REQUIRED' });
    }
    next();
  } catch { res.status(401).json({ message: 'সেশন শেষ হয়েছে বা অবৈধ লগইন' }); }
}
const allow = (...roles) => (req,res,next) => roles.includes(req.user.role) ? next() : res.status(403).json({message:'এই কাজের অনুমতি নেই'});
const audit = async (user, action, entity, entityId=null, details={}) => {
  try { await pool.query('INSERT INTO audit_logs(user_id,action,entity,entity_id,details) VALUES($1,$2,$3,$4,$5)', [user,action,entity,entityId,JSON.stringify(details)]); } catch {}
};
