app.post('/api/notifications/send',auth,allow('super_admin','admin','head_teacher','assistant_head_teacher'),async(req,res)=>{const x=req.body||{};if(!x.title_bn||!x.body)return res.status(400).json({message:'শিরোনাম ও বার্তা আবশ্যক'});const recipients=Array.isArray(x.recipient_user_ids)?[...new Set(x.recipient_user_ids.filter(Boolean))]:[];if(!recipients.length)return res.status(400).json({message:'কমপক্ষে একজন প্রাপক নির্বাচন করুন'});const client=await pool.connect();try{await client.query('BEGIN');for(const uid of recipients){await client.query('INSERT INTO notifications(recipient_user_id,title_bn,title_en,body,type,priority,action_url,created_by) VALUES($1,$2,$3,$4,$5,$6,$7,$8)',[uid,x.title_bn,x.title_en||null,x.body,x.type||'general',x.priority||'normal',x.action_url||null,req.user.sub]);await client.query('INSERT INTO communication_messages(sender_user_id,recipient_user_id,subject_bn,body,channel,status,sent_at) VALUES($1,$2,$3,$4,\'in_app\',\'sent\',NOW())',[req.user.sub,uid,x.title_bn,x.body])}await client.query('COMMIT');await audit(req.user.sub,'send','notification',null,{recipient_count:recipients.length,type:x.type||'general'});res.status(201).json({count:recipients.length,message:`${recipients.length} জনকে নোটিফিকেশন পাঠানো হয়েছে`})}catch(e){await client.query('ROLLBACK');res.status(400).json({message:'নোটিফিকেশন পাঠানো ব্যর্থ'})}finally{client.release()}});
app.post('/api/notifications/broadcast',auth,allow('super_admin','admin','head_teacher'),async(req,res)=>{const x=req.body||{};if(!x.title_bn||!x.body||!x.recipient_group)return res.status(400).json({message:'শিরোনাম, বার্তা ও গ্রুপ আবশ্যক'});const group=x.recipient_group;const allowedGroups=['all','teacher','student','guardian','staff'];if(!allowedGroups.includes(group))return res.status(400).json({message:'অবৈধ গ্রুপ'});const condition=group==='all'?'u.is_active=true':`u.is_active=true AND r.name=${'$1'}`;const params=group==='all'?[]:[group];const users=await pool.query(`SELECT u.id FROM users u JOIN roles r ON r.id=u.role_id WHERE ${condition}`,params);if(!users.rowCount)return res.status(400).json({message:'এই গ্রুপে কোনো সক্রিয় ব্যবহারকারী নেই'});const client=await pool.connect();try{await client.query('BEGIN');for(const u of users.rows){await client.query('INSERT INTO notifications(recipient_user_id,title_bn,title_en,body,type,priority,created_by) VALUES($1,$2,$3,$4,$5,$6,$7)',[u.id,x.title_bn,x.title_en||null,x.body,x.type||'general',x.priority||'normal',req.user.sub]);await client.query('INSERT INTO communication_messages(sender_user_id,recipient_user_id,recipient_group,subject_bn,body,channel,status,sent_at) VALUES($1,$2,$3,$4,$5,\'in_app\',\'sent\',NOW())',[req.user.sub,u.id,group,x.title_bn,x.body])}await client.query('COMMIT');await audit(req.user.sub,'broadcast','notification',null,{group,count:users.rowCount});res.status(201).json({count:users.rowCount,message:`${users.rowCount} জনকে নোটিফিকেশন পাঠানো হয়েছে`})}catch(e){await client.query('ROLLBACK');res.status(400).json({message:'Broadcast ব্যর্থ'})}finally{client.release()}});
app.post('/api/notifications/attendance-alerts',auth,allow('super_admin','admin','head_teacher','assistant_head_teacher'),async(req,res)=>{const days=Math.min(Math.max(Number(req.body?.days||3),2),30);const q=await pool.query(`WITH recent AS (SELECT a.student_id,COUNT(*) FILTER(WHERE a.status='absent') absent_days FROM attendance a WHERE a.attendance_date>=CURRENT_DATE-$1::int GROUP BY a.student_id HAVING COUNT(*) FILTER(WHERE a.status='absent')>=2) SELECT s.id,s.student_id,s.name_bn,s.guardian_phone,g.id guardian_user_id FROM recent r JOIN students s ON s.id=r.student_id LEFT JOIN guardian_student_links gsl ON gsl.student_id=s.id LEFT JOIN users g ON g.id=gsl.guardian_user_id AND g.is_active=true`,[days]);let count=0;for(const r of q.rows){if(r.guardian_user_id){const exists=await pool.query(`SELECT 1 FROM notifications WHERE recipient_user_id=$1 AND type='attendance' AND entity_type='student' AND entity_id=$2 AND created_at::date=CURRENT_DATE LIMIT 1`,[r.guardian_user_id,String(r.id)]);if(!exists.rowCount){await pool.query('INSERT INTO notifications(recipient_user_id,title_bn,body,type,priority,entity_type,entity_id,created_by) VALUES($1,$2,$3,\'attendance\',\'high\',\'student\',$4,$5)',[r.guardian_user_id,'উপস্থিতি সতর্কতা',`${r.name_bn} গত ${days} দিনে একাধিক দিন অনুপস্থিত ছিল। অনুগ্রহ করে উপস্থিতির বিষয়টি দেখুন।`,String(r.id),req.user.sub]);count++}}}await audit(req.user.sub,'attendance-alerts','notification',null,{days,count});res.json({students:q.rowCount,notified:count})});

