app.get('/api/finance/fees',auth,async(req,res)=>{const {q='',status='',student_id=''}=req.query;const p=[],w=[];if(q){p.push(`%${q}%`);w.push(`(s.name_bn ILIKE $${p.length} OR s.student_id ILIKE $${p.length} OR f.fee_type ILIKE $${p.length} OR COALESCE(f.receipt_no,'') ILIKE $${p.length})`)}if(status){p.push(status);w.push(`f.status=$${p.length}`)}if(student_id){p.push(student_id);w.push(`f.student_id=$${p.length}`)}const sql=`SELECT f.*,s.student_id,s.name_bn,s.roll_no,COALESCE((SELECT SUM(fp.amount) FROM fee_payments fp WHERE fp.fee_id=f.id),0) paid_amount FROM fees f LEFT JOIN students s ON s.id=f.student_id ${w.length?'WHERE '+w.join(' AND '):''} ORDER BY f.due_date DESC NULLS LAST,f.id DESC`;res.json((await pool.query(sql,p)).rows)});
