app.post('/api/finance/payments',auth,allow('super_admin','admin','head_teacher','accountant'),async(req,res)=>{const client=await pool.connect();try{const x=req.body||{};if(!x.fee_id||!x.amount)throw new Error('ফি ও পরিমাণ আবশ্যক');await client.query('BEGIN');const r=await client.query('INSERT INTO fee_payments(fee_id,amount,payment_method,reference,paid_at,received_by) VALUES($1,$2,$3,$4,COALESCE($5::timestamptz,NOW()),$6) RETURNING *',[x.fee_id,Number(x.amount),x.payment_method||'cash',x.reference||null,x.paid_at||null,req.user.sub]);const sum=await client.query('SELECT amount FROM fees WHERE id=$1 UNION ALL SELECT COALESCE(SUM(amount),0) FROM fee_payments WHERE fee_id=$1',[x.fee_id]);const fee=await client.query('SELECT amount FROM fees WHERE id=$1',[x.fee_id]);const paid=(await client.query('SELECT COALESCE(SUM(amount),0) v FROM fee_payments WHERE fee_id=$1',[x.fee_id])).rows[0].v;const status=Number(paid)>=Number(fee.rows[0].amount)?'paid':Number(paid)>0?'partial':'due';await client.query('UPDATE fees SET status=$1,paid_at=CASE WHEN $1=\'paid\' THEN NOW() ELSE paid_at END,receipt_no=COALESCE(receipt_no,\'RCPT-\'||id) WHERE id=$2',[status,x.fee_id]);await client.query('COMMIT');res.status(201).json(r.rows[0])}catch(e){await client.query('ROLLBACK');res.status(400).json({message:e.message||'Payment সংরক্ষণ ব্যর্থ'})}finally{client.release()}});
