app.post('/api/auth/login', loginLimiter, async (req,res)=>{
  try {
    const {loginId,password} = req.body || {};
    if(!loginId || !password) return res.status(400).json({message:'Login ID ও Password দিন'});
    const q=await pool.query('SELECT u.*,r.name role_name,r.label_bn role_label FROM users u JOIN roles r ON r.id=u.role_id WHERE u.login_id=$1 AND u.is_active=true',[String(loginId).trim()]);
    if(!q.rowCount || !(await bcrypt.compare(password,q.rows[0].password_hash))) return res.status(401).json({message:'Login ID বা Password ভুল'});
    const u=q.rows[0]; await pool.query('UPDATE users SET last_login_at=NOW(),updated_at=NOW() WHERE id=$1',[u.id]);
    await audit(u.id,'login','auth',null,{login_id:u.login_id});
    res.json({token:sign(u),user:{id:u.id,loginId:u.login_id,name:u.full_name,role:u.role_name,roleLabel:u.role_label,mustChangePassword:u.must_change_password}});
  } catch(e) { console.error(e); res.status(500).json({message:'লগইন সার্ভার ত্রুটি'}); }
});
