app.post('/api/auth/change-password',auth,async(req,res)=>{
  try { const {currentPassword,newPassword}=req.body||{}; if(!currentPassword||!newPassword||newPassword.length<8)return res.status(400).json({message:'বর্তমান password এবং কমপক্ষে ৮ অক্ষরের নতুন password দিন'});
    const q=await pool.query('SELECT password_hash FROM users WHERE id=$1 AND is_active=true',[req.user.sub]); if(!q.rowCount||!(await bcrypt.compare(currentPassword,q.rows[0].password_hash)))return res.status(400).json({message:'বর্তমান password সঠিক নয়'});
    const hash=await bcrypt.hash(newPassword,12); await pool.query('UPDATE users SET password_hash=$1,must_change_password=false,auth_token_version=auth_token_version+1,updated_at=NOW() WHERE id=$2',[hash,req.user.sub]); await audit(req.user.sub,'change_password','user',req.user.sub); res.json({ok:true,relogin_required:true,message:'Password সফলভাবে পরিবর্তন হয়েছে। নিরাপত্তার জন্য আবার Login করুন।'});
  } catch(e){res.status(500).json({message:'Password পরিবর্তন ব্যর্থ'})}
});

