app.get('/api/public/student-stats',async(req,res)=>{
 try {
  const [total,teachers,gender,religion,classes]=await Promise.all([
   pool.query("SELECT COUNT(*)::int AS count FROM students WHERE status='active'"),
   pool.query("SELECT COUNT(*)::int AS count FROM teachers WHERE status='active'"),
   pool.query("SELECT COALESCE(NULLIF(TRIM(gender),''),'অনির্দিষ্ট') label, COUNT(*)::int count FROM students WHERE status='active' GROUP BY 1 ORDER BY count DESC"),
   pool.query(`SELECT 
      CASE 
        WHEN religion ILIKE '%ইসলাম%' OR religion ILIKE '%islam%' OR religion ILIKE '%মুসলিম%' OR religion ILIKE '%muslim%' THEN 'ইসলাম'
        WHEN religion ILIKE '%হিন্দু%' OR religion ILIKE '%hindu%' OR religion ILIKE '%সনাতন%' OR religion ILIKE '%sanatan%' THEN 'হিন্দু'
        WHEN religion ILIKE '%বৌদ্ধ%' OR religion ILIKE '%buddhist%' OR religion ILIKE '%buddhism%' THEN 'বৌদ্ধ'
        WHEN religion ILIKE '%খ্রিষ্টান%' OR religion ILIKE '%খ্রিস্টান%' OR religion ILIKE '%christian%' THEN 'খ্রিষ্টান'
        WHEN religion ILIKE '%অন্যান্য%' OR religion ILIKE '%other%' THEN 'অন্যান্য'
        ELSE COALESCE(NULLIF(TRIM(religion),''),'ইসলাম')
      END label, COUNT(*)::int count FROM students WHERE status='active' GROUP BY 1 ORDER BY count DESC`),
   pool.query("SELECT class_name label, COUNT(*)::int count FROM students WHERE status='active' GROUP BY class_name ORDER BY class_name")
  ]);
  const make=(rows)=>rows.map(x=>({label:x.label,count:x.count}));
  res.json({total:total.rows[0].count,teachers:teachers.rows[0].count,gender:make(gender.rows),religion:make(religion.rows),classes:make(classes.rows)});
 } catch(e) { res.status(503).json({message:'শিক্ষার্থী পরিসংখ্যান সাময়িকভাবে পাওয়া যাচ্ছে না'}); }
});

app.get('/api/public/contact',async(req,res)=>{
 try {
  const teachers=await pool.query(`SELECT id,name_bn,name_en,designation,subject,phone,email,photo_url,public_contact_role
    FROM teachers WHERE status='active' AND public_contact_enabled=true
    AND (public_contact_role IN ('head_teacher','assistant_head_teacher','ict_teacher')
      OR designation ILIKE ANY(ARRAY['প্রধান শিক্ষক%','head teacher%','সহকারী প্রধান শিক্ষক%','assistant head teacher%','আইসিটি শিক্ষক%','ICT teacher%'])
      OR subject ILIKE ANY(ARRAY['%ICT%','%আইসিটি%']))
    ORDER BY CASE
      WHEN public_contact_role='head_teacher' OR designation ILIKE 'প্রধান শিক্ষক%' OR designation ILIKE 'head teacher%' THEN 1
      WHEN public_contact_role='assistant_head_teacher' OR designation ILIKE 'সহকারী প্রধান শিক্ষক%' OR designation ILIKE 'assistant head teacher%' THEN 2
      WHEN public_contact_role='ict_teacher' OR designation ILIKE '%আইসিটি শিক্ষক%' OR designation ILIKE '%ICT teacher%' OR subject ILIKE '%ICT%' OR subject ILIKE '%আইসিটি%' THEN 3 ELSE 9 END, updated_at DESC NULLS LAST, name_bn`).rows;
  const staff=await pool.query(`SELECT id,name_bn,name_en,designation,phone,email,photo_url,public_contact_role
    FROM staff WHERE status='active' AND public_contact_enabled=true
    AND (public_contact_role='office_assistant' OR designation ILIKE ANY(ARRAY['%অফিস সহকারী%','%office assistant%','%office staff%']))
    ORDER BY CASE WHEN public_contact_role='office_assistant' THEN 1 ELSE 2 END, updated_at DESC NULLS LAST, name_bn`).rows;
  const pick=(rows,role)=>rows.find(x=>x.public_contact_role===role)||rows.find(x=>role==='head_teacher' ? /^(প্রধান শিক্ষক|head teacher)/i.test(String(x.designation||'')) : role==='assistant_head_teacher' ? /^(সহকারী প্রধান শিক্ষক|assistant head teacher)/i.test(String(x.designation||'')) : /আইসিটি শিক্ষক|ICT teacher/i.test(String(x.designation||'')) || /ICT|আইসিটি/i.test(String(x.subject||'')));
  const office=staff.find(x=>x.public_contact_role==='office_assistant')||staff[0]||null;
  res.json({contacts:[
    {key:'head',role:'প্রধান শিক্ষক',role_en:'Head Teacher',person:pick(teachers,'head_teacher')},
    {key:'assistant',role:'সহকারী প্রধান শিক্ষক',role_en:'Assistant Head Teacher',person:pick(teachers,'assistant_head_teacher')},
    {key:'ict',role:'আইসিটি শিক্ষক',role_en:'ICT Teacher',person:pick(teachers,'ict_teacher')},
    {key:'office',role:'অফিস সহকারী',role_en:'Office Assistant',person:office}
  ]});
 } catch(e) { res.json({contacts:[]}); }
});
