app.post('/api/admin/custom-features',auth,allow('super_admin','admin','head_teacher'),async(req,res)=>{try{const x=req.body||{};const target=String(x.target_url||'').trim();if(!x.title_bn||!target)return res.status(400).json({message:'নাম ও Target URL আবশ্যক'});if(!(/^(#|\/(?!\/)|https:\/\/)/.test(target)))return res.status(400).json({message:'Target URL শুধু internal path, hash অথবা HTTPS URL হতে পারবে'});const q=await pool.query(`INSERT INTO custom_features(title_bn,title_en,description,icon,target_url,placement,enabled,sort_order,created_by) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9) RETURNING *`,[String(x.title_bn).slice(0,180),x.title_en||null,x.description||null,x.icon||'✨',target,['admin','public','both'].includes(x.placement)?x.placement:'admin',x.enabled!==false,Number(x.sort_order||0),req.user.sub]);await audit(req.user.sub,'create','custom_feature',q.rows[0].id);res.status(201).json(q.rows[0]);}catch(e){res.status(400).json({message:'Custom feature যোগ করা যায়নি'})}});
app.patch('/api/admin/custom-features/:id',auth,allow('super_admin','admin','head_teacher'),async(req,res)=>{try{const x=req.body||{};const target=x.target_url==null?null:String(x.target_url).trim();if(target!==null&&!(/^(#|\/(?!\/)|https:\/\/)/.test(target)))return res.status(400).json({message:'Target URL শুধু internal path, hash অথবা HTTPS URL হতে পারবে'});const q=await pool.query(`UPDATE custom_features SET title_bn=COALESCE($1,title_bn),title_en=$2,description=$3,icon=$4,target_url=COALESCE($5,target_url),placement=COALESCE($6,placement),enabled=COALESCE($7,enabled),sort_order=COALESCE($8,sort_order),updated_at=NOW() WHERE id=$9 RETURNING *`,[x.title_bn||null,x.title_en||null,x.description||null,x.icon||'✨',target,['admin','public','both'].includes(x.placement)?x.placement:null,typeof x.enabled==='boolean'?x.enabled:null,x.sort_order==null?null:Number(x.sort_order),req.params.id]);if(!q.rowCount)return res.status(404).json({message:'Custom feature পাওয়া যায়নি'});res.json(q.rows[0]);}catch(e){res.status(400).json({message:'Custom feature আপডেট ব্যর্থ'})}});
app.delete('/api/admin/custom-features/:id',auth,allow('super_admin','admin','head_teacher'),async(req,res)=>{try{const q=await pool.query('DELETE FROM custom_features WHERE id=$1 RETURNING id',[req.params.id]);if(!q.rowCount)return res.status(404).json({message:'Custom feature পাওয়া যায়নি'});await audit(req.user.sub,'delete','custom_feature',req.params.id);res.json({ok:true})}catch(e){res.status(400).json({message:'Custom feature মুছতে ব্যর্থ'})}});

