app.post('/api/users',auth,allow('super_admin','admin'),async(req,res)=>{
  try {
    const {login_id,full_name,email,phone,password,role='teacher'}=req.body||{};
    if(!login_id||!full_name||!password||password.length<8||!validRoles.has(role))return res.status(400).json({message:'Login ID, নাম, বৈধ role এবং কমপক্ষে ৮ অক্ষরের password আবশ্যক'});
    if(role==='super_admin' && req.user.role!=='super_admin')return res.status(403).json({message:'শুধু Super Admin নতুন Super Admin তৈরি করতে পারবেন'});
    const roleQ=await pool.query('SELECT id FROM roles WHERE name=$1',[role]);
    const hash=await bcrypt.hash(password,12);
    const q=await pool.query('INSERT INTO users(login_id,full_name,email,phone,password_hash,role_id,must_change_password) VALUES($1,$2,$3,$4,$5,$6,true) RETURNING id,login_id,full_name,email,phone,is_active,must_change_password',[String(login_id).trim(),full_name,email||null,phone||null,hash,roleQ.rows[0].id]);
    await audit(req.user.sub,'create','user',q.rows[0].id,{role,login_id}); res.status(201).json(q.rows[0]);
  } catch(e){res.status(400).json({message:e.code==='23505'?'এই Login ID আগে থেকেই আছে':'ব্যবহারকারী তৈরি ব্যর্থ'})}
});
app.patch('/api/users/:id',auth,allow('super_admin','admin'),async(req,res)=>{
  try {
    const {full_name,email,phone,is_active,role}=req.body||{};
    const target=await pool.query('SELECT u.id,r.name role_name FROM users u JOIN roles r ON r.id=u.role_id WHERE u.id=$1',[req.params.id]);
    if(!target.rowCount)return res.status(404).json({message:'ব্যবহারকারী পাওয়া যায়নি'});
    if(target.rows[0].role_name==='super_admin' && req.user.role!=='super_admin')return res.status(403).json({message:'Super Admin account পরিবর্তনের অনুমতি নেই'});
    if(role==='super_admin' && req.user.role!=='super_admin')return res.status(403).json({message:'শুধু Super Admin এই role দিতে পারবেন'});
    let q;
    if(role){ if(!validRoles.has(role))return res.status(400).json({message:'অবৈধ role'}); const rq=await pool.query('SELECT id FROM roles WHERE name=$1',[role]); q=await pool.query('UPDATE users SET full_name=COALESCE($1,full_name),email=$2,phone=$3,is_active=COALESCE($4,is_active),role_id=$5,auth_token_version=auth_token_version+1,updated_at=NOW() WHERE id=$6 RETURNING id,login_id,full_name,email,phone,is_active,must_change_password',[full_name??null,email??null,phone??null,is_active??null,rq.rows[0].id,req.params.id]); }
    else q=await pool.query('UPDATE users SET full_name=COALESCE($1,full_name),email=$2,phone=$3,is_active=COALESCE($4,is_active),auth_token_version=auth_token_version+1,updated_at=NOW() WHERE id=$5 RETURNING id,login_id,full_name,email,phone,is_active,must_change_password',[full_name??null,email??null,phone??null,is_active??null,req.params.id]);
    await audit(req.user.sub,'update','user',req.params.id,{role,is_active}); res.json(q.rows[0]);
  } catch(e){console.error(e);res.status(400).json({message:'ব্যবহারকারী আপডেট ব্যর্থ'})}
});
