app.post('/api/users/:id/invalidate-sessions',auth,allow('super_admin','admin'),async(req,res)=>{
  try {
    const target=await pool.query('SELECT u.id,r.name role_name FROM users u JOIN roles r ON r.id=u.role_id WHERE u.id=$1',[req.params.id]);
    if(!target.rowCount)return res.status(404).json({message:'ব্যবহারকারী পাওয়া যায়নি'});
    if(target.rows[0].role_name==='super_admin' && req.user.role!=='super_admin')return res.status(403).json({message:'Super Admin session invalidate করতে পারবেন না'});
    await pool.query('UPDATE users SET auth_token_version=auth_token_version+1,updated_at=NOW() WHERE id=$1',[req.params.id]);
    await audit(req.user.sub,'invalidate_sessions','user',req.params.id);
    res.json({ok:true,message:'এই account-এর সব পুরোনো session বাতিল করা হয়েছে'});
  } catch(e){res.status(500).json({message:'Session invalidate ব্যর্থ'})}
});

app.post('/api/users/provision-profile',auth,allow('super_admin','admin'),async(req,res)=>{
  const x=req.body||{}; const entity=String(x.entity_type||'').trim(); const entityId=String(x.entity_id||'').trim();
  const roleMap={student:'student',teacher:'teacher',staff:'staff'}; const tableMap={student:'students',teacher:'teachers',staff:'staff'};
  if(!roleMap[entity]||!entityId||!x.login_id||!x.password||String(x.password).length<8)return res.status(400).json({message:'Profile, Login ID এবং কমপক্ষে ৮ অক্ষরের password আবশ্যক'});
  const client=await pool.connect();
  try{
    await client.query('BEGIN');
    const table=tableMap[entity];
    const profile=await client.query(`SELECT * FROM ${table} WHERE id=$1 FOR UPDATE`,[entityId]);
    if(!profile.rowCount){await client.query('ROLLBACK');return res.status(404).json({message:'Profile পাওয়া যায়নি'})}
    if(profile.rows[0].user_id){await client.query('ROLLBACK');return res.status(400).json({message:'এই profile-এর সঙ্গে ইতিমধ্যে একটি login account যুক্ত আছে'})}
    const roleQ=await client.query('SELECT id FROM roles WHERE name=$1',[roleMap[entity]]);
    if(!roleQ.rowCount){await client.query('ROLLBACK');return res.status(500).json({message:'Role configuration পাওয়া যায়নি'})}
    const fullName=profile.rows[0].name_bn || profile.rows[0].name_en || x.full_name || x.login_id;
    const email=x.email||profile.rows[0].email||null, phone=x.phone||profile.rows[0].phone||null;
    const hash=await bcrypt.hash(String(x.password),12);
    const uq=await client.query('INSERT INTO users(login_id,full_name,email,phone,password_hash,role_id,must_change_password) VALUES($1,$2,$3,$4,$5,$6,true) RETURNING id,login_id,full_name,email,phone,is_active,must_change_password',[String(x.login_id).trim(),fullName,email,phone,hash,roleQ.rows[0].id]);
    await client.query(`UPDATE ${table} SET user_id=$1,updated_at=NOW() WHERE id=$2`,[uq.rows[0].id,entityId]);
    await audit(req.user.sub,'provision_profile_account',entity,entityId,{user_id:uq.rows[0].id,login_id:uq.rows[0].login_id});
    await client.query('COMMIT'); res.status(201).json({...uq.rows[0],entity_type:entity,entity_id:entityId,message:'Profile-এর সঙ্গে login account সফলভাবে তৈরি ও সংযুক্ত হয়েছে'});
  }catch(e){await client.query('ROLLBACK'); console.error(e);res.status(400).json({message:e.code==='23505'?'এই Login ID আগে থেকেই আছে বা profile link conflict হয়েছে':'Account provisioning ব্যর্থ'});}finally{client.release()}
});

app.post('/api/users/provision-guardian-from-student',auth,allow('super_admin','admin'),async(req,res)=>{
  const x=req.body||{}; const studentId=String(x.student_id||'').trim(); const relation=String(x.relation||'guardian').trim();
  if(!studentId||!x.login_id||!x.password||String(x.password).length<8)return res.status(400).json({message:'শিক্ষার্থী, Login ID এবং কমপক্ষে ৮ অক্ষরের password আবশ্যক'});
  const allowedRelations=new Set(['guardian','father','mother','local_guardian']);
  if(!allowedRelations.has(relation))return res.status(400).json({message:'অবৈধ guardian relation'});
  const client=await pool.connect();
  try{
    await client.query('BEGIN');
    const st=await client.query(`SELECT * FROM students WHERE id=$1 FOR UPDATE`,[studentId]);
    if(!st.rowCount){await client.query('ROLLBACK');return res.status(404).json({message:'শিক্ষার্থী পাওয়া যায়নি'})}
    const student=st.rows[0];
    let guardianName=String(x.guardian_name||'').trim();
    if(!guardianName){
      guardianName=relation==='mother'?String(student.mother_name||'').trim():relation==='father'?String(student.father_name||'').trim():String(student.guardian_name||'').trim();
    }
    if(!guardianName)return res.status(400).json({message:'এই শিক্ষার্থীর guardian/father/mother নাম পাওয়া যায়নি; নাম দিন'});
    const roleQ=await client.query('SELECT id FROM roles WHERE name=$1',['guardian']);
    if(!roleQ.rowCount){await client.query('ROLLBACK');return res.status(500).json({message:'Guardian role configuration পাওয়া যায়নি'})}
    const phone=String(x.phone||student.guardian_phone||'').trim()||null;
    const email=String(x.email||'').trim()||null;
    const hash=await bcrypt.hash(String(x.password),12);
    const uq=await client.query('INSERT INTO users(login_id,full_name,email,phone,password_hash,role_id,must_change_password) VALUES($1,$2,$3,$4,$5,$6,true) RETURNING id,login_id,full_name,email,phone,is_active,must_change_password',[String(x.login_id).trim(),guardianName,email,phone,hash,roleQ.rows[0].id]);
    const link=await client.query(`INSERT INTO guardian_student_links(guardian_user_id,student_id,relation) VALUES($1,$2,$3) ON CONFLICT(guardian_user_id,student_id) DO UPDATE SET relation=EXCLUDED.relation RETURNING *`,[uq.rows[0].id,student.id,relation]);
    await audit(req.user.sub,'provision_guardian_account','student',student.id,{user_id:uq.rows[0].id,login_id:uq.rows[0].login_id,relation});
    await client.query('COMMIT');
    res.status(201).json({...uq.rows[0],student_id:student.id,relation,link_id:link.rows[0].id,message:'Guardian account তৈরি এবং শিক্ষার্থীর সঙ্গে link সফল হয়েছে'});
  }catch(e){await client.query('ROLLBACK');console.error(e);res.status(400).json({message:e.code==='23505'?'এই Login ID আগে থেকেই আছে':'Guardian account provisioning ব্যর্থ'});}finally{client.release()}
});

app.post('/api/users/:id/reset-password',auth,allow('super_admin','admin'),async(req,res)=>{
  try { const {newPassword}=req.body||{}; if(!newPassword||newPassword.length<8)return res.status(400).json({message:'কমপক্ষে ৮ অক্ষরের নতুন password দিন'}); const target=await pool.query('SELECT u.id,r.name role_name FROM users u JOIN roles r ON r.id=u.role_id WHERE u.id=$1',[req.params.id]); if(!target.rowCount)return res.status(404).json({message:'ব্যবহারকারী পাওয়া যায়নি'}); if(target.rows[0].role_name==='super_admin'&&req.user.role!=='super_admin')return res.status(403).json({message:'Super Admin password reset করতে পারবেন না'}); const hash=await bcrypt.hash(newPassword,12); await pool.query('UPDATE users SET password_hash=$1,must_change_password=true,auth_token_version=auth_token_version+1,updated_at=NOW() WHERE id=$2',[hash,req.params.id]); await audit(req.user.sub,'reset_password','user',req.params.id); res.json({ok:true,message:'Password reset হয়েছে; পরের login-এ পরিবর্তন করতে হবে'}); } catch(e){res.status(500).json({message:'Password reset ব্যর্থ'})}
});

