app.get('/api/students',auth,async(req,res)=>{const {q='',class_name='',section='',status='',custom_field_key='',custom_field_value=''}=req.query;const params=[];const where=[];if(q){params.push(`%${q}%`);where.push(`(name_bn ILIKE $${params.length} OR name_en ILIKE $${params.length} OR student_id ILIKE $${params.length} OR guardian_name ILIKE $${params.length} OR father_name ILIKE $${params.length} OR mother_name ILIKE $${params.length} OR father_mobile ILIKE $${params.length} OR mother_mobile ILIKE $${params.length} OR guardian_phone ILIKE $${params.length})`)}if(class_name){params.push(class_name);where.push(`class_name=$${params.length}`)}if(section){params.push(section);where.push(`section=$${params.length}`)}if(status){params.push(status);where.push(`status=$${params.length}`)}if(custom_field_key&&custom_field_value){params.push(custom_field_key);params.push(`%${custom_field_value}%`);where.push(`COALESCE(extended_profile->'custom_fields'->>$${params.length-1},'') ILIKE $${params.length}`)}const pageRaw=Number.parseInt(req.query.page||'',10);const pageSizeRaw=Number.parseInt(req.query.page_size||'',10);const paginated=Number.isFinite(pageRaw)||Number.isFinite(pageSizeRaw);const page=Number.isFinite(pageRaw)?Math.max(pageRaw,1):1;const pageSize=Number.isFinite(pageSizeRaw)?Math.min(Math.max(pageSizeRaw,10),200):50;const base='FROM students '+(where.length?'WHERE '+where.join(' AND '):'');if(!paginated){const sql='SELECT * '+base+' ORDER BY class_name,roll_no NULLS LAST,name_bn';return res.json((await pool.query(sql,params)).rows)}const countQ=await pool.query('SELECT COUNT(*)::int count '+base,params);const offset=(page-1)*pageSize;const q2=await pool.query('SELECT * '+base+' ORDER BY class_name,roll_no NULLS LAST,name_bn LIMIT $'+(params.length+1)+' OFFSET $'+(params.length+2),[...params,pageSize,offset]);res.json({items:q2.rows,page,page_size:pageSize,total:countQ.rows[0].count,total_pages:Math.ceil(countQ.rows[0].count/pageSize)});});
