app.get('/api/attendance/roster',auth,async(req,res)=>{const {date,class_name='',section=''}=req.query;if(!date)return res.status(400).json({message:'তারিখ দিন'});const p=[date],w=["s.status='active'"];if(class_name){p.push(class_name);w.push('s.class_name=$'+p.length)}if(section){p.push(section);w.push('s.section=$'+p.length)}const paginated=req.query.page!=null||req.query.page_size!=null;if(!paginated){const q=await pool.query(`SELECT s.id,s.student_id,s.roll_no,s.name_bn,s.class_name,s.section,COALESCE(a.status,'present') status,COALESCE(a.remarks,'') remarks FROM students s LEFT JOIN attendance a ON a.student_id=s.id AND a.attendance_date=$1::date WHERE ${w.join(' AND ')} ORDER BY s.class_name,s.section,s.roll_no NULLS LAST,s.name_bn`,p);return res.json(q.rows)}const page=Math.max(1,Number.parseInt(req.query.page,10)||1),size=Math.min(200,Math.max(10,Number.parseInt(req.query.page_size,10)||50));const base=`FROM students s LEFT JOIN attendance a ON a.student_id=s.id AND a.attendance_date=$1::date WHERE ${w.join(' AND ')}`;const count=await pool.query(`SELECT COUNT(*)::int count FROM students s WHERE ${w.join(' AND ')}`,p);const q=await pool.query(`SELECT s.id,s.student_id,s.roll_no,s.name_bn,s.class_name,s.section,COALESCE(a.status,'present') status,COALESCE(a.remarks,'') remarks ${base} ORDER BY s.class_name,s.section,s.roll_no NULLS LAST,s.name_bn LIMIT $${p.length+1} OFFSET $${p.length+2}`,[...p,size,(page-1)*size]);res.json({items:q.rows,page,page_size:size,total:count.rows[0].count,total_pages:Math.ceil(count.rows[0].count/size)});});
app.get('/api/attendance/monthly-summary',auth,async(req,res)=>{const {month}=req.query;if(!month||!/^[0-9]{4}-[0-9]{2}$/.test(month))return res.status(400).json({message:'YYYY-MM month দিন'});const q=await pool.query(`SELECT s.student_id,s.name_bn,s.class_name,s.section,s.roll_no,COUNT(a.id)::int total,COUNT(*) FILTER(WHERE a.status='present')::int present,COUNT(*) FILTER(WHERE a.status='absent')::int absent,COUNT(*) FILTER(WHERE a.status='late')::int late,ROUND(100.0*COUNT(*) FILTER(WHERE a.status='present')/NULLIF(COUNT(a.id),0),1) attendance_pct FROM students s LEFT JOIN attendance a ON a.student_id=s.id AND to_char(a.attendance_date,'YYYY-MM')=$1 WHERE s.status='active' GROUP BY s.id ORDER BY s.class_name,s.section,s.roll_no NULLS LAST,s.name_bn`,[month]);res.json(q.rows)});
app.get('/api/attendance/risk',auth,async(req,res)=>{const q=await pool.query(`SELECT s.id,s.student_id,s.name_bn,s.class_name,s.section,s.roll_no,COUNT(a.id)::int total,COUNT(*) FILTER(WHERE a.status='absent')::int absent,ROUND(100.0*COUNT(*) FILTER(WHERE a.status='absent')/NULLIF(COUNT(a.id),0),1) absent_pct FROM students s JOIN attendance a ON a.student_id=s.id WHERE s.status='active' AND a.attendance_date>=CURRENT_DATE-INTERVAL '30 days' GROUP BY s.id HAVING COUNT(*) FILTER(WHERE a.status='absent')>=3 OR (100.0*COUNT(*) FILTER(WHERE a.status='absent')/NULLIF(COUNT(a.id),0))>=15 ORDER BY absent DESC,absent_pct DESC`);res.json(q.rows)});
