app.get('/api/routines',auth,async(req,res)=>{
  try {
    const {class_name='',section='',teacher_id='',day_of_week=''}=req.query;
    const p=[],w=[];
    if(class_name){p.push(class_name);w.push(`r.class_name=$${p.length}`)}
    if(section){p.push(section);w.push(`COALESCE(r.section,'')=$${p.length}`)}
    if(teacher_id){p.push(teacher_id);w.push(`r.teacher_id=$${p.length}`)}
    if(day_of_week){p.push(Number(day_of_week));w.push(`r.day_of_week=$${p.length}`)}
    const sql=`SELECT r.*,s.name_bn subject_name,t.name_bn teacher_name FROM routines r LEFT JOIN subjects s ON s.id=r.subject_id LEFT JOIN teachers t ON t.id=r.teacher_id ${w.length?'WHERE '+w.join(' AND '):''} ORDER BY r.day_of_week,r.start_time,r.class_name,r.section`;
    res.json((await pool.query(sql,p)).rows);
  } catch(e){res.status(500).json({message:'রুটিন লোড ব্যর্থ'})}
});
