 if(req.user.role==='teacher'){const allowed=await pool.query(`SELECT 1 FROM routines WHERE teacher_id=$1 AND class_name=$2 AND ($3='' OR section=$3) AND subject_id=$4 LIMIT 1`,[t.rows[0].id,className,section,subjectId]);if(!allowed.rowCount)return res.status(403).json({message:'এই শ্রেণি ও বিষয়ের নম্বর আপনার দায়িত্বে নেই'});}
 const meta=await pool.query(`SELECT es.*,s.code,s.name_bn FROM exam_subjects es JOIN subjects s ON s.id=es.subject_id WHERE es.exam_id=$1 AND es.subject_id=$2`,[examId,subjectId]); if(!meta.rowCount)return res.status(404).json({message:'এই পরীক্ষায় বিষয় সেটআপ হয়নি'});
 const params=[examId,className,subjectId]; let sectionWhere=''; if(section){params.push(section);sectionWhere=' AND s.section=$4';}
