app.post('/api/portal/teacher/marks-save',auth,allow('teacher','head_teacher','assistant_head_teacher'),async(req,res)=>{const {exam_id,class_name,section='',records}=req.body||{};if(!exam_id||!class_name||!Array.isArray(records))return res.status(400).json({message:'পরীক্ষা, শ্রেণি ও marks records আবশ্যক'});try{const t=await pool.query('SELECT id FROM teachers WHERE user_id=$1 LIMIT 1',[req.user.sub]);if(!t.rowCount)return res.status(403).json({message:'শিক্ষক প্রোফাইল সংযুক্ত নেই'});const client=await pool.connect();try{await client.query('BEGIN');for(const x of records){const studentCheck=await client.query(`SELECT 1 FROM students WHERE id=$1 AND status='active' AND class_name=$2 AND ($3='' OR section=$3)`,[x.student_id,class_name,section||'']);if(!studentCheck.rowCount)throw new Error('শিক্ষার্থী এই শ্রেণি/শাখার নয়');const meta=await client.query('SELECT full_marks,written_max,mcq_max,practical_max FROM exam_subjects WHERE exam_id=$1 AND subject_id=$2',[exam_id,x.subject_id]);const m=meta.rows[0];if(!m)throw new Error('পরীক্ষার বিষয় সেটআপ হয়নি');if(req.user.role==='teacher'){const allowed=await client.query(`SELECT 1 FROM routines WHERE teacher_id=$1 AND class_name=$2 AND ($3='' OR section=$3) AND subject_id=$4 LIMIT 1`,[t.rows[0].id,class_name,section||'',x.subject_id]);if(!allowed.rowCount)throw new Error('এই শ্রেণি ও বিষয়ের নম্বর আপনার দায়িত্বে নেই');}const vals=['written','mcq','practical'].map(k=>x[k]===''||x[k]==null?null:Number(x[k]));const maxes=[Number(m.written_max||0),Number(m.mcq_max||0),Number(m.practical_max||0)];vals.forEach((v,i)=>{if(v!=null&&(v<0||v>maxes[i]))throw new Error('কম্পোনেন্টের নির্ধারিত পূর্ণ নম্বরের বেশি দেওয়া যাবে না')});const total=vals.reduce((a,v)=>a+(v||0),0);if(total>Number(m.full_marks))throw new Error('পূর্ণ নম্বরের বেশি দেওয়া যাবে না');await client.query(`INSERT INTO marks(exam_id,student_id,subject_id,written,mcq,practical,total,absent,remarks) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9) ON CONFLICT(exam_id,student_id,subject_id) DO UPDATE SET written=EXCLUDED.written,mcq=EXCLUDED.mcq,practical=EXCLUDED.practical,total=EXCLUDED.total,absent=EXCLUDED.absent,remarks=EXCLUDED.remarks,processed_at=NULL`,[exam_id,x.student_id,x.subject_id,...vals,total,!!x.absent,x.remarks||null]);}await client.query('COMMIT');await audit(req.user.sub,'teacher_bulk_marks','marks',null,{exam_id,count:records.length});res.json({ok:true,count:records.length});}catch(e){await client.query('ROLLBACK');res.status(400).json({message:e.message||'নম্বর সংরক্ষণ ব্যর্থ'});}finally{client.release()}}catch(e){res.status(500).json({message:'নম্বর সংরক্ষণ ব্যর্থ'})}});
app.get('/api/portal/links',auth,allow('super_admin','admin','head_teacher'),async(req,res)=>{try{const q=await pool.query(`SELECT gsl.id,gsl.relation,gsl.guardian_user_id,gsl.student_id,u.login_id guardian_login,u.full_name guardian_name,s.student_id student_code,s.name_bn student_name,s.class_name,s.roll_no FROM guardian_student_links gsl JOIN users u ON u.id=gsl.guardian_user_id JOIN students s ON s.id=gsl.student_id ORDER BY s.class_name,s.roll_no NULLS LAST,s.name_bn,u.full_name`);res.json(q.rows)}catch(e){res.status(500).json({message:'Guardian link তালিকা লোড ব্যর্থ'})}});
