app.post('/api/online-exams/:id/start',auth,allow('student'),async(req,res)=>{const st=await pool.query('SELECT id,class_name FROM students WHERE user_id=$1 LIMIT 1',[req.user.sub]);if(!st.rowCount)return res.status(400).json({message:'Student profile link নেই'});const ex=await pool.query('SELECT * FROM online_exams WHERE id=$1 AND status=\'published\'',[req.params.id]);if(!ex.rowCount)return res.status(404).json({message:'অনলাইন পরীক্ষা পাওয়া যায়নি'});const exam=ex.rows[0];if(exam.class_name!==st.rows[0].class_name)return res.status(403).json({message:'এই পরীক্ষা আপনার শ্রেণির জন্য নয়'});const now=Date.now();if(exam.starts_at && now<new Date(exam.starts_at).getTime())return res.status(409).json({message:'পরীক্ষা এখনও শুরু হয়নি'});if(exam.ends_at && now>=new Date(exam.ends_at).getTime())return res.status(409).json({message:'পরীক্ষার সময় শেষ হয়েছে'});const q=await pool.query(`INSERT INTO online_exam_attempts(online_exam_id,student_id) VALUES($1,$2) ON CONFLICT(online_exam_id,student_id) DO UPDATE SET status=CASE WHEN online_exam_attempts.status='submitted' THEN online_exam_attempts.status ELSE 'in_progress' END RETURNING *`,[req.params.id,st.rows[0].id]);res.json({attempt:q.rows[0],exam,questions:(await pool.query(`SELECT oq.question_id,oq.display_order,qb.question_type,qb.question_bn,qb.question_en,qb.options,qb.marks FROM online_exam_questions oq JOIN question_bank qb ON qb.id=oq.question_id WHERE oq.online_exam_id=$1 ORDER BY oq.display_order,oq.id`,[req.params.id])).rows});});
app.post('/api/online-exams/attempts/:attemptId/submit',auth,allow('student'),async(req,res)=>{const st=await pool.query('SELECT id FROM students WHERE user_id=$1 LIMIT 1',[req.user.sub]);if(!st.rowCount)return res.status(400).json({message:'Student profile link নেই'});const attempt=await pool.query(`SELECT a.*,e.starts_at,e.ends_at,e.total_marks,e.duration_minutes FROM online_exam_attempts a JOIN online_exams e ON e.id=a.online_exam_id WHERE a.id=$1 AND a.student_id=$2 AND a.status<>'submitted'`,[req.params.attemptId,st.rows[0].id]);if(!attempt.rowCount)return res.status(404).json({message:'Attempt পাওয়া যায়নি'});const at=attempt.rows[0];const now=Date.now();const deadline=at.ends_at?new Date(at.ends_at).getTime():new Date(at.started_at).getTime()+Number(at.duration_minutes||30)*60000;if(now>deadline)return res.status(409).json({message:'পরীক্ষার সময় শেষ হয়েছে; উত্তর জমা দেওয়া যাচ্ছে না'});const answers=Array.isArray(req.body?.answers)?req.body.answers:[];const client=await pool.connect();try{await client.query('BEGIN');let score=0;const allowed=await client.query(`SELECT oq.question_id,qb.correct_answer,qb.marks FROM online_exam_questions oq JOIN question_bank qb ON qb.id=oq.question_id WHERE oq.online_exam_id=$1`,[at.online_exam_id]);const allowedMap=new Map(allowed.rows.map(q=>[String(q.question_id),q]));for(const a of answers){const q=allowedMap.get(String(a.question_id));if(!q)continue;const correct=String(a.answer??'').trim()===String(q.correct_answer??'').trim();const awarded=correct?Number(q.marks):0;score+=awarded;await client.query(`INSERT INTO online_exam_answers(attempt_id,question_id,answer,is_correct,marks_awarded) VALUES($1,$2,$3,$4,$5) ON CONFLICT(attempt_id,question_id) DO UPDATE SET answer=EXCLUDED.answer,is_correct=EXCLUDED.is_correct,marks_awarded=EXCLUDED.marks_awarded`,[req.params.attemptId,a.question_id,a.answer??null,correct,awarded])}score=Math.min(score,Number(at.total_marks||score));const u=await client.query(`UPDATE online_exam_attempts SET submitted_at=NOW(),score=$1,status='submitted' WHERE id=$2 RETURNING *`,[score,req.params.attemptId]);await client.query('COMMIT');res.json(u.rows[0])}catch(e){await client.query('ROLLBACK');res.status(400).json({message:'Online exam submit ব্যর্থ'})}finally{client.release()}});


