const aiRoles=['super_admin','admin','head_teacher','assistant_head_teacher','teacher','student'];
function tutorReply(message){
  const m=String(message||'').trim();
  if(!m) return 'আপনার প্রশ্নটি লিখুন। আমি ধাপে ধাপে বুঝিয়ে দেওয়ার চেষ্টা করব।';
  const lower=m.toLowerCase();
  if(/gpa|গ্রেড|জিপিএ/.test(lower)) return 'GPA বুঝতে প্রতিটি বিষয়ের grade point বিবেচনা করতে হয়। আপনার পরীক্ষার বিষয়ভিত্তিক নম্বর দিলে আমি ধাপে ধাপে ফলাফল বিশ্লেষণের কাঠামো দেখাতে পারি।';
  if(/পড়|study|রুটিন|সময়/.test(lower)) return 'আজকের পড়াশোনাকে ৩ ভাগে ভাগ করুন: ১) দুর্বল অধ্যায় ৩০–৪৫ মিনিট, ২) নতুন বিষয় ৩০ মিনিট, ৩) MCQ/CQ অনুশীলন ২০–৩০ মিনিট। প্রতিটি সেশনের শেষে ভুলগুলো নোট করুন।';
  if(/গণিত|math/.test(lower)) return 'গণিতে আগে ধারণা, তারপর উদাহরণ, এরপর নিজে ৩–৫টি সমস্যা সমাধান করুন। ভুল হলে সমাধান না দেখে কোথায় ভুল হয়েছে চিহ্নিত করুন।';
  if(/ইংরেজি|english/.test(lower)) return 'ইংরেজিতে প্রতিদিন vocabulary, grammar এবং writing—এই তিনটি অংশে অল্প অল্প অনুশীলন করুন। ভুল বাক্যগুলো আলাদা খাতায় লিখে পুনরায় ঠিক করুন।';
  if(/বিজ্ঞান|science|পদার্থ|রসায়ন|জীববিজ্ঞান/.test(lower)) return 'বিজ্ঞানের প্রশ্নে শুধু মুখস্থ না করে কারণ–ফলাফল, সংজ্ঞা, চিত্র ও প্রয়োগ একসঙ্গে অনুশীলন করুন। অধ্যায় শেষে ১০টি MCQ ও ২টি CQ দিয়ে নিজেকে যাচাই করুন।';
  return 'চমৎকার প্রশ্ন। উত্তর বের করার আগে বিষয়টি ছোট ছোট অংশে ভাগ করি। আপনি চাইলে শ্রেণি, বিষয় ও অধ্যায়ের নামসহ প্রশ্নটি দিলে আমি ধাপে ধাপে ব্যাখ্যা করার উপযোগী উত্তর তৈরি করতে পারব।';
}
