app.post('/api/ai/conversations/:id/messages',auth,async(req,res)=>{const message=String(req.body?.message||'').trim();if(!message)return res.status(400).json({message:'প্রশ্ন লিখুন'});const owner=await pool.query('SELECT id FROM ai_conversations WHERE id=$1 AND user_id=$2',[req.params.id,req.user.sub]);if(!owner.rowCount)return res.status(404).json({message:'Conversation পাওয়া যায়নি'});const client=await pool.connect();try{await client.query('BEGIN');await client.query('INSERT INTO ai_messages(conversation_id,role,message) VALUES($1,\'user\',$2)',[req.params.id,message]);const reply=tutorReply(message);const a=await client.query('INSERT INTO ai_messages(conversation_id,role,message) VALUES($1,\'assistant\',$2) RETURNING *',[req.params.id,reply]);await client.query('UPDATE ai_conversations SET updated_at=NOW() WHERE id=$1',[req.params.id]);await client.query('COMMIT');res.status(201).json(a.rows[0])}catch(e){await client.query('ROLLBACK');res.status(400).json({message:'AI response সংরক্ষণ ব্যর্থ'})}finally{client.release()}});
app.get('/api/ai/student-insights',auth,async(req,res)=>{let studentId=req.query.student_id; if(req.user.role==='student'){const s=await pool.query('SELECT id FROM students WHERE user_id=$1 LIMIT 1',[req.user.sub]);studentId=s.rows[0]?.id;} if(!studentId)return res.status(400).json({message:'student_id আবশ্যক'}); if(req.user.role==='student'){const ok=await pool.query('SELECT 1 FROM students WHERE id=$1 AND user_id=$2',[studentId,req.user.sub]);if(!ok.rowCount)return res.status(403).json({message:'অনুমতি নেই'});} const [att,marks]=await Promise.all([pool.query(`SELECT COUNT(*) FILTER(WHERE status='present')::int present,COUNT(*) FILTER(WHERE status='absent')::int absent,COUNT(*) FILTER(WHERE status='late')::int late,COUNT(*)::int total FROM attendance WHERE student_id=$1`,[studentId]),pool.query(`SELECT s.name_bn subject_name,COALESCE(AVG(m.total),0)::numeric(8,2) avg_marks,COUNT(m.id)::int exams FROM marks m JOIN subjects s ON s.id=m.subject_id WHERE m.student_id=$1 GROUP BY s.id,s.name_bn ORDER BY avg_marks ASC`,[studentId])]);const a=att.rows[0];const rate=a.total?Math.round(Number(a.present)/Number(a.total)*100):null;const weak=marks.rows.filter(x=>Number(x.avg_marks)<50).slice(0,5);const tips=[];if(rate!==null&&rate<80)tips.push('উপস্থিতি ৮০%-এর নিচে; নিয়মিত উপস্থিতিকে প্রথম অগ্রাধিকার দিন।');if(weak.length)tips.push('কম নম্বরের বিষয়গুলোতে অতিরিক্ত অনুশীলন ও শিক্ষক সহায়তা নিন।');if(!tips.length)tips.push('বর্তমান তথ্য অনুযায়ী নিয়মিত পড়াশোনা ও মডেল টেস্ট চালিয়ে যান।');res.json({attendance:{...a,rate},subjects:marks.rows,weakSubjects:weak,tips});});
app.post('/api/ai/study-plans',auth,allow('super_admin','admin','head_teacher','assistant_head_teacher','teacher','student'),async(req,res)=>{let studentId=req.body?.student_id;if(req.user.role==='student'){const s=await pool.query('SELECT id FROM students WHERE user_id=$1 LIMIT 1',[req.user.sub]);studentId=s.rows[0]?.id;}if(!studentId)return res.status(400).json({message:'student_id আবশ্যক'});const start=req.body?.start_date||new Date().toISOString().slice(0,10);const end=req.body?.end_date||new Date(Date.now()+13*86400000).toISOString().slice(0,10);const weak=await pool.query(`SELECT s.name_bn subject_name,AVG(m.total)::numeric(8,2) avg_marks FROM marks m JOIN subjects s ON s.id=m.subject_id WHERE m.student_id=$1 GROUP BY s.id,s.name_bn ORDER BY avg_marks ASC LIMIT 3`,[studentId]);const plan=weak.rows.map((x,i)=>({day:i+1,subject:x.subject_name,focus:'দুর্বল অধ্যায় পুনরাবৃত্তি + ১০টি MCQ + ২টি CQ',minutes:60}));plan.push({day:plan.length+1,subject:'সকল বিষয়',focus:'সাপ্তাহিক মডেল টেস্ট ও ভুল বিশ্লেষণ',minutes:90});const q=await pool.query(`INSERT INTO study_plans(student_id,title_bn,goal,start_date,end_date,plan_json,created_by) VALUES($1,$2,$3,$4,$5,$6,$7) RETURNING *`,[studentId,req.body?.title_bn||'ব্যক্তিগত Study Plan',req.body?.goal||'দুর্বল বিষয় উন্নয়ন ও পরীক্ষার প্রস্তুতি',start,end,JSON.stringify(plan),req.user.sub]);res.status(201).json(q.rows[0])});
