app.get('/api/reports/overview',auth,async(_,res)=>{try{
 const [students,teachers,attendance,finance,admission,library,results]=await Promise.all([
  pool.query("SELECT COUNT(*)::int total,COUNT(*) FILTER(WHERE status='active')::int active,COUNT(*) FILTER(WHERE status<>'active')::int inactive FROM students"),
  pool.query("SELECT COUNT(*)::int total,COUNT(*) FILTER(WHERE status='active')::int active FROM teachers"),
  pool.query("SELECT COUNT(*)::int total,COUNT(*) FILTER(WHERE status='present')::int present,COUNT(*) FILTER(WHERE status='absent')::int absent,COUNT(*) FILTER(WHERE status='late')::int late FROM attendance WHERE attendance_date>=CURRENT_DATE-30"),
  pool.query("SELECT COALESCE((SELECT SUM(amount) FROM fees),0)::numeric billed,COALESCE((SELECT SUM(amount) FROM fee_payments),0)::numeric collected,COALESCE((SELECT SUM(amount) FROM fees WHERE status<>'paid'),0)::numeric due,COALESCE((SELECT SUM(amount) FROM expenses),0)::numeric expense"),
  pool.query("SELECT COUNT(*)::int total,COUNT(*) FILTER(WHERE status='admitted')::int admitted,COUNT(*) FILTER(WHERE status IN ('submitted','under_review','waiting'))::int pending FROM admission_applications WHERE application_date>=CURRENT_DATE-365"),
  pool.query("SELECT COUNT(*)::int total,COUNT(*) FILTER(WHERE returned_at IS NULL)::int outstanding FROM library_loans"),
  pool.query("SELECT COUNT(*)::int marks_count,COALESCE(AVG(total),0)::numeric(8,2) avg_marks,COUNT(*) FILTER(WHERE total<33)::int below_pass FROM marks")
 ]);
 res.json({students:students.rows[0],teachers:teachers.rows[0],attendance:attendance.rows[0],finance:finance.rows[0],admission:admission.rows[0],library:library.rows[0],results:results.rows[0]});
}catch(e){res.status(500).json({message:'রিপোর্ট তৈরি ব্যর্থ'})}});
app.get('/api/reports/attendance-trend',auth,async(req,res)=>{const days=Math.min(90,Math.max(7,Number(req.query.days||30)));res.json((await pool.query(`SELECT attendance_date,COUNT(*)::int total,COUNT(*) FILTER(WHERE status='present')::int present,COUNT(*) FILTER(WHERE status='absent')::int absent,COUNT(*) FILTER(WHERE status='late')::int late,ROUND(COUNT(*) FILTER(WHERE status='present')::numeric*100/NULLIF(COUNT(*),0),2) rate FROM attendance WHERE attendance_date>=CURRENT_DATE-$1::int GROUP BY attendance_date ORDER BY attendance_date`,[days])).rows)});
app.get('/api/reports/class-attendance',auth,async(_,res)=>{res.json((await pool.query(`SELECT s.class_name,COUNT(a.id)::int records,COUNT(a.id) FILTER(WHERE a.status='present')::int present,COUNT(a.id) FILTER(WHERE a.status='absent')::int absent,ROUND(COUNT(a.id) FILTER(WHERE a.status='present')::numeric*100/NULLIF(COUNT(a.id),0),2) rate FROM students s LEFT JOIN attendance a ON a.student_id=s.id GROUP BY s.class_name ORDER BY s.class_name`)).rows)});
app.get('/api/reports/result-summary',auth,async(_,res)=>{res.json((await pool.query(`SELECT s.class_name,sub.name_bn subject_name,COUNT(m.id)::int entries,ROUND(AVG(m.total),2) avg_marks,COUNT(*) FILTER(WHERE m.total<33)::int below_pass FROM marks m JOIN students s ON s.id=m.student_id JOIN subjects sub ON sub.id=m.subject_id GROUP BY s.class_name,sub.name_bn ORDER BY s.class_name,sub.name_bn`)).rows)});
app.get('/api/reports/finance-monthly',auth,async(_,res)=>{res.json((await pool.query(`WITH months AS (SELECT generate_series(date_trunc('month',CURRENT_DATE)-interval '11 months',date_trunc('month',CURRENT_DATE),interval '1 month') month) SELECT to_char(months.month,'YYYY-MM') month,COALESCE((SELECT SUM(amount) FROM fee_payments WHERE paid_at>=months.month AND paid_at<months.month+interval '1 month'),0)::numeric collected,COALESCE((SELECT SUM(amount) FROM expenses WHERE expense_date>=months.month::date AND expense_date<(months.month+interval '1 month')::date),0)::numeric expense FROM months ORDER BY months.month`)).rows)});
app.get('/api/reports/admission-summary',auth,async(_,res)=>{res.json((await pool.query(`SELECT academic_year,applied_class,COUNT(*)::int applications,COUNT(*) FILTER(WHERE status='admitted')::int admitted,COUNT(*) FILTER(WHERE status='rejected')::int rejected FROM admission_applications GROUP BY academic_year,applied_class ORDER BY academic_year DESC,applied_class`)).rows)});
app.get('/api/reports/student-risk',auth,async(_,res)=>{res.json((await pool.query(`WITH a AS (SELECT student_id,COUNT(*) total,COUNT(*) FILTER(WHERE status='present') present,COUNT(*) FILTER(WHERE status='absent') absent FROM attendance WHERE attendance_date>=CURRENT_DATE-30 GROUP BY student_id),m AS (SELECT student_id,AVG(total) avg_marks FROM marks GROUP BY student_id) SELECT s.id,s.student_id,s.roll_no,s.name_bn,s.class_name,COALESCE(a.total,0)::int attendance_records,COALESCE(ROUND(a.present::numeric*100/NULLIF(a.total,0),2),0) attendance_rate,COALESCE(a.absent,0)::int absent_days,COALESCE(ROUND(m.avg_marks,2),0) avg_marks,CASE WHEN COALESCE(a.present::numeric*100/NULLIF(a.total,0),100)<70 OR COALESCE(m.avg_marks,100)<40 THEN 'high' WHEN COALESCE(a.present::numeric*100/NULLIF(a.total,0),100)<80 OR COALESCE(m.avg_marks,100)<50 THEN 'medium' ELSE 'low' END risk FROM students s LEFT JOIN a ON a.student_id=s.id LEFT JOIN m ON m.student_id=s.id WHERE s.status='active' ORDER BY CASE WHEN COALESCE(a.present::numeric*100/NULLIF(a.total,0),100)<70 OR COALESCE(m.avg_marks,100)<40 THEN 1 WHEN COALESCE(a.present::numeric*100/NULLIF(a.total,0),100)<80 OR COALESCE(m.avg_marks,100)<50 THEN 2 ELSE 3 END,s.class_name,s.roll_no LIMIT 500`)).rows)});
app.get('/api/reports/attendance-summary',auth,async(_,res)=>{const q=await pool.query(`SELECT attendance_date,COUNT(*)::int total,COUNT(*) FILTER(WHERE status='present')::int present,COUNT(*) FILTER(WHERE status='absent')::int absent,COUNT(*) FILTER(WHERE status='late')::int late FROM attendance GROUP BY attendance_date ORDER BY attendance_date DESC LIMIT 31`);res.json(q.rows)});
