const server = app.listen(PORT,()=>console.log('Magra School API V117 running on '+PORT));
const shutdown = async (signal) => { console.log(signal+' received; shutting down'); server.close(async () => { await pool.end(); process.exit(0); }); setTimeout(() => process.exit(1), 10000).unref(); };
process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));
